        subtitle: '생리로 인해 못 한 금식 일수를 세어 줘요.',
        answer: 'AWA는 특히 라마단 동안 생리로 인해 못 한 금식 일수를 세는 카운터를 제공할 수 있어요. 또한 라마단이 끝난 뒤 카다 금식을 계획하도록 부드러운 리마인더도 보내 드려요.',
