        answer: 'AWA는 니파스의 최대 기간에 대해 선택한 종교적 기준을 보여 줄 수 있고, 검증된 콘텐츠가 다루는 범위에서는 법학파 간의 차이도 함께 알려 줘요. 앱은 하나의 수치를 절대적인 진리로 제시하지 않아요.',
