        answer: 'AWA는 이스티하다와 그것이 신앙 생활에 의미하는 바에 대한 일반적인 교육용 콘텐츠를 제공할 수 있어요. 앱은 개인 맞춤 파트와를 내리지 않으며, 종교 콘텐츠는 공인된 권위 있는 기관의 검증을 받도록 되어 있어요.',
